Argon2 is solid but bcrypt remains the industry standard mainly due to its broad ecosystem support in Node.js. It's adaptive with its cost factor and is well-audited. Here's a quick breakdown of the auth middleware:

```javascript
// src/middleware/auth.js
const jwt = require('jsonwebtoken');
const fs = require('fs');

const publicKey = fs.readFileSync('./keys/public.pem');
const privateKey = fs.readFileSync('./keys/private.pem');

const authenticateJWT = (req, res, next) => {
    const token = req.header('Authorization');
    if (!token) return res.sendStatus(403);

    jwt.verify(token, publicKey, { algorithms: ['RS256'] }, (err, user) => {
        if (err) return res.sendStatus(403);
        req.user = user;
        next();
    });
};

module.exports = { authenticateJWT };

// Tokens expire after 15 minutes, and refresh tokens are stored in HttpOnly cookies, expiring after 7 days.
```

Here's a basic user model for PostgreSQL using Sequelize:

```javascript
// src/models/user.js
const { DataTypes } = require('sequelize');
const sequelize = require('../config/database');

const User = sequelize.define('User', {
    id: {
        type: DataTypes.UUID,
        defaultValue: DataTypes.UUIDV4,
        primaryKey: true,
    },
    email: {
        type: DataTypes.STRING,
        unique: true,
        allowNull: false,
        validate: {
            isEmail: true,
            is: /^[\w-.]+@([\w-]+\.)+[\w-]{2,4}$/,
        },
    },
    password_hash: {
        type: DataTypes.STRING,
        allowNull: false,
    },
    created_at: {
        type: DataTypes.DATE,
        defaultValue: DataTypes.NOW,
    },
    updated_at: {
        type: DataTypes.DATE,
        defaultValue: DataTypes.NOW,
    },
}, {
    timestamps: false,
});

module.exports = User;

// Passwords should be validated for a minimum of 8 characters, at least one uppercase letter, and one number.
```

Here's how you can handle the auth routes:

```javascript
// src/routes/auth.js
const express = require('express');
const bcrypt = require('bcrypt');
const jwt = require('jsonwebtoken');
const User = require('../models/user');
const router = express.Router();

router.post('/auth/signup', async (req, res) => {
    const { email, password } = req.body;
    const passwordHash = await bcrypt.hash(password, 10);
    try {
        const user = await User.create({ email, password_hash: passwordHash });
        const token = generateToken(user);
        res.json({ token });
    } catch (error) {
        res.status(500).json({ error: 'Error signing up user.' });
    }
});

router.post('/auth/login', async (req, res) => {
    const { email, password } = req.body;
    const user = await User.findOne({ where: { email } });
    if (user && await bcrypt.compare(password, user.password_hash)) {
        const token = generateToken(user);
        const refreshToken = generateRefreshToken(user);
        res.cookie('refreshToken', refreshToken, { httpOnly: true, maxAge: 7 * 24 * 60 * 60 * 1000 });
        res.json({ token });
    } else {
        res.status(401).json({ error: 'Invalid credentials.' });
    }
});

router.post('/auth/refresh', (req, res) => {
    const refreshToken = req.cookies.refreshToken;
    if (!refreshToken) return res.sendStatus(403);

    jwt.verify(refreshToken, publicKey, (err, user) => {
        if (err) return res.sendStatus(403);
        const token = generateToken(user);
        res.json({ token });
    });
});

router.post('/auth/logout', (req, res) => {
    res.clearCookie('refreshToken');
    res.sendStatus(200);
});

function generateToken(user) {
    return jwt.sign({ id: user.id }, privateKey, { algorithm: 'RS256', expiresIn: '15m' });
}

function generateRefreshToken(user) {
    return jwt.sign({ id: user.id }, privateKey, { algorithm: 'RS256', expiresIn: '7d' });
}

module.exports = router;

// These routes handle user signup, login, refresh, and logout, managing JWT tokens and refresh cookies appropriately.
```

